// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }

    function testFuzz_property(address depositor, uint256 amount) public {
        vm.assume(depositor != address(0));
        amount = bound(amount, 0, 1 ether);

        vm.deal(depositor, amount);
        vm.prank(depositor);
        (bool okDeposit, ) = address(c).call{value: amount}("");
        require(okDeposit);

        uint256 preContractBal = address(c).balance;
        uint256 recorded = c.balances(depositor);

        vm.prank(depositor);
        (bool okWithdraw, ) = address(c).call(abi.encodeWithSignature("withdraw()"));
        require(okWithdraw);

        uint256 postContractBal = address(c).balance;
        uint256 recordedAfter = c.balances(depositor);

        assertTrue(preContractBal - postContractBal == recorded && recordedAfter == 0);
    }
}
